<?php require "config/db.php";$error="";if($_SERVER["REQUEST_METHOD"]==="POST"){$name=trim($_POST["name"]??"");$email=strtolower(trim($_POST["email"]??""));$pass=$_POST["password"]??"";if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){$error="Enter a name, valid email and password with at least 8 characters.";}else{try{$s=$pdo->prepare("INSERT INTO users(name,email,password) VALUES(?,?,?)");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION["user"]=["id"=>$pdo->lastInsertId(),"name"=>$name,"email"=>$email,"role"=>"customer"];header("Location: index.php");exit;}catch(PDOException $e){$error="That email is already registered.";}}} ?>
